import numpy as np

def simpsons_rule(f, a, b, n=100):
    if n % 2 != 0:
        n += 1
    h = (b - a) / n
    x = np.linspace(a, b, n + 1)
    y = f(x)
    integral = h/3 * (y[0] + 4*np.sum(y[1:-1:2]) + 2*np.sum(y[2:-1:2]) + y[-1])
    return integral

def simpsons_38_rule(f, a, b, n=99):
    while n % 3 != 0:
        n += 1
    h = (b - a) / n
    x = np.linspace(a, b, n + 1)
    y = f(x)
    integral = y[0] + y[-1]
    for i in range(1, n):
        if i % 3 == 0:
            integral += 2 * y[i]
        else:
            integral += 3 * y[i]
    integral *= 3 * h / 8
    return integral

def romberg_integration(f, a, b, max_order=6):
    R = np.zeros((max_order, max_order))
    for i in range(max_order):
        n = 2**i
        R[i, 0] = trapezoidal_rule(f, a, b, n)
    for j in range(1, max_order):
        for i in range(j, max_order):
            R[i, j] = R[i, j-1] + (R[i, j-1] - R[i-1, j-1]) / (4**j - 1)
    return R[max_order-1, max_order-1], R

def trapezoidal_rule(f, a, b, n=100):
    h = (b - a) / n
    x = np.linspace(a, b, n + 1)
    y = f(x)
    return h * (y[0]/2 + np.sum(y[1:-1]) + y[-1]/2)

result = simpsons_rule(lambda x: np.exp(-x**2), 0, 1, n=100)
exact = 0.7468241328124271
print(f"Simpson's: {result:.10f}")
print(f"Error: {abs(result - exact):.2e}")
